const icons={book:'<path d="M4 3h6c2 0 2 2 2 2s0-2 2-2h6v16h-6c-2 0-2 2-2 2s0-2-2-2H4z"/><path d="M12 5v16"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/><path d="m20 2 .6 1.4L22 4l-1.4.6L20 6l-.6-1.4L18 4l1.4-.6z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 18 6-6 4 4 3-7 5 6"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="15" cy="17" r="3" fill="white"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1.5.5-1.5 2-1.5 2M12 17h.01"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',logout:'<path d="M10 3H4v18h6M9 12h12m-5-5 5 5-5 5"/>',undo:'<path d="M3 10h11a6 6 0 1 1 0 12M3 10l5-5M3 10l5 5"/>',redo:'<path d="M21 10H10a6 6 0 1 0 0 12m15-12-5-5m5 5-5 5"/>',warn:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',layout:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',cloud:'<path d="M7 18a5 5 0 1 1-1-10 6 6 0 0 1 12 1 4.5 4.5 0 0 1 0 9M9 15l3 3 5-5"/>'};
const I=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const E=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
let state={user:null,projects:[],view:'dashboard',p:null,tab:'structure',chapter:0,search:'',filter:'all',job:null,page:0,zoom:100,assistant:false},saveTimer,savePromise=null,dirty=false,jobTimer,assetCallback;
const styles=['photoréaliste','éditorial','cinématique','3D','aquarelle','cartoon','minimaliste','business','éducatif','luxe'];
async function api(url,method='GET',body){const opts={method,headers:{'X-Studio':'1'}};if(body instanceof FormData)opts.body=body;else if(body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}const r=await fetch('/api'+url,opts);let data;try{data=await r.json()}catch{throw Error('Réponse serveur invalide.')}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'La requête n’a pas pu être traitée.');return data}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),6000)}
function modal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><button class="iconbtn close" onclick="closeModal()" aria-label="Fermer">${I('close')}</button>${html}</div></div>`}
function closeModal(){$('#modal-root').innerHTML=''}
const fileUrl=(p,name,download=false)=>`/api/projects/${p.id}/files/${name}?${download?'download=1&':''}v=${p.render_revision??p.revision??0}`;
function shell(content){const u=state.user;$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" onclick="navigate('dashboard');return false"><div class="brandmark">${I('book')}</div><span>AI BOOK STUDIO</span></a><div class="workspace flex"><div class="wslogo">A</div><span style="flex:1">Mon espace créatif</span>${I('down')}</div><div class="navlabel">ESPACE DE TRAVAIL</div><nav><button class="navitem ${state.view==='dashboard'||state.view==='editor'?'active':''}" onclick="navigate('dashboard')">${I('grid')}<span>Mes livres</span><span class="count">${state.projects.length}</span></button><button class="navitem" onclick="newBook()">${I('plus')}<span>Nouveau livre</span></button><button class="navitem" onclick="demoModal()">${I('spark')}<span>Découvrir le studio</span></button></nav><div class="side-bottom"><button class="navitem ${state.view==='settings'?'active':''}" onclick="navigate('settings')">${I('settings')}<span>Paramètres IA</span></button><button class="navitem ${state.view==='help'?'active':''}" onclick="navigate('help')">${I('help')}<span>Aide & ressources</span></button><div class="localbox"><div class="flex between"><h4>Votre atelier, sans abonnement</h4></div><div style="height:1px;background:var(--line);margin:12px 0"></div><p>Import, mise en page et export.<br>Vos premiers livres commencent ici.</p><span class="pill green"><span class="dot"></span> Mode gratuit</span></div><div class="profile flex"><div class="avatar">${E((u?.name||'Mon espace').slice(0,2).toUpperCase())}</div><div class="profile-info" style="flex:1"><div class="name">${E(u?.name||'Bienvenue au studio')}</div><div class="muted">${u?.email?'Compte personnel':u?'Session découverte':'Espace personnel'}</div></div><button class="iconbtn" title="${u?'Se déconnecter':'Se connecter'}" onclick="${u?'logout()':'authModal()'}">${I(u?'logout':'arrow')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu iconbtn" aria-label="Ouvrir le menu" onclick="$('.sidebar').classList.toggle('open')">${I('menu')}</button><span>Espace de travail</span>${I('chevron')}<b>${{dashboard:'Mes livres',editor:'Éditeur',settings:'Paramètres IA',help:'Aide & ressources'}[state.view]}</b></div><div class="flex right"><span class="flex gap top-label">${I('shield')} Vos fichiers restent privés</span><span class="vline"></span><span class="pill purple">ÉDITION LOCALE</span></div></header><div class="content">${content}</div></main>`;if(state.view==='editor'&&state.p?.book)assistantWidget()}
async function navigate(view){try{if(dirty)await flush();state.view=view;state.assistant=false;clearTimeout(jobTimer);if(view==='dashboard'){if(state.user)state.projects=await api('/projects');renderDashboard()}else if(view==='settings'){if(!await ensureUser())return;await renderSettings()}else if(view==='help')renderHelp()}catch(e){toast(e.message)}}
function renderDashboard(){const ps=state.projects,ready=ps.filter(p=>p.result),pages=ready.reduce((n,p)=>n+p.result.pages,0);shell(`<div class="welcome flex between"><div><h1>Vos idées méritent un livre.</h1><p>Transformez vos PDF en livres professionnels avec l’IA.</p></div><button class="btn primary" onclick="newBook()">${I('plus')} Nouveau livre</button></div><section class="hero"><div class="hero-copy"><div class="eyebrow flex gap">${I('spark')} DE L’IDÉE À LA DERNIÈRE PAGE</div><h2>Un manuscrit. Des possibilités.<br>Votre prochain livre.</h2><p>Donnez une nouvelle dimension à vos textes.<br>Structurez, illustrez et composez, dans un seul atelier.</p><button class="btn" onclick="demoModal()">Explorer un livre de démonstration ${I('arrow')}</button></div><div class="hero-art"><span class="decor-star">✧</span><div class="mockbook"><small>LES NOUVEAUX POSSIBLES</small><h3>Entreprendre<br>autrement</h3><p>Un guide pour les entrepreneurs africains</p><div class="author">AÏCHA MENSAH</div></div><div class="floating-tag flex">${I('spark')} Du PDF au livre, tout simplement.</div></div></section><div class="stats"><div class="stat"><div class="stat-icon">${I('book')}</div><div><b>${ps.length.toString().padStart(2,'0')}</b><p>Livres dans votre bibliothèque</p></div></div><div class="stat"><div class="stat-icon">${I('check')}</div><div><b>${ready.length.toString().padStart(2,'0')}</b><p>Livres avec un export créé</p></div></div><div class="stat"><div class="stat-icon">${I('file')}</div><div><b>${pages.toString().padStart(2,'0')}</b><p>Pages intérieures composées</p></div></div></div><div class="section-heading flex between"><div class="flex"><h2>Mes livres</h2><span class="pill">${ps.length} projet${ps.length>1?'s':''}</span></div><div class="flex gap"><label class="search">${I('search')}<input aria-label="Rechercher un livre" placeholder="Rechercher un livre…" value="${E(state.search)}" oninput="state.search=this.value;renderProjectGrid()"></label><select class="filter" aria-label="Filtrer les projets" onchange="state.filter=this.value;renderProjectGrid()"><option value="all">Tous les projets</option><option value="ready" ${state.filter==='ready'?'selected':''}>Avec un export</option><option value="imported" ${state.filter==='imported'?'selected':''}>À analyser</option></select></div></div><div class="projects" id="project-grid"></div><div class="workflow"><h4>Du document au livre, un parcours simplifié</h4><div class="workflow-line">${[['upload','Importez votre PDF'],['file','Structurez le contenu'],['image','Ajoutez vos illustrations'],['layout','Composez vos pages'],['download','Exportez votre livre']].map(([icon,label],i)=>`${i?'<span class="arrow">→</span>':''}<span>${I(icon)} ${label}</span>`).join('')}</div></div><footer class="footer"><span>Conçu pour les idées qui méritent d’être partagées.</span><span class="flex gap">${I('lock')} Fichiers privés · Sans API payante obligatoire</span></footer>`);renderProjectGrid()}
function renderProjectGrid(){if(!$('#project-grid'))return;const ps=state.projects.filter(p=>p.title.toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='all'||(state.filter==='ready'?p.result:!p.result)));$('#project-grid').innerHTML=ps.map(p=>`<article class="project-card"><div class="project-cover" onclick="openProject('${p.id}')" role="button" tabindex="0" onkeydown="if(event.key==='Enter')openProject('${p.id}')">${p.result?`<img src="${fileUrl(p,'thumb.png')}" alt="Couverture de ${E(p.title)}">`:`<div class="pdf-placeholder">${I('file')}<div>${E(p.title.slice(0,65))}</div></div>`}<span class="pill ${p.result?'green':'purple'}"><span class="dot"></span>${p.result?(p.revision===p.render_revision?'Export disponible':'Modifié'):'À analyser'}</span></div><div class="project-info"><h3>${E(p.title)}</h3><p>${p.result?p.result.pages+' pages composées':p.source.pages+' pages source'} <span style="margin:0 4px">·</span> ${new Date(p.updated).toLocaleDateString('fr-FR',{day:'numeric',month:'short'})}</p><div class="card-actions"><button class="btn small" onclick="openProject('${p.id}')">${I('edit')} Modifier</button><div class="flex" style="gap:0">${p.result?`<button class="iconbtn" title="Aperçu" onclick="openProject('${p.id}','preview')">${I('eye')}</button><button class="iconbtn" title="Exporter" onclick="openExport('${p.id}')">${I('download')}</button>`:''}<button class="iconbtn" title="Supprimer le projet" onclick="deleteProject('${p.id}')">${I('trash')}</button></div></div></div></article>`).join('')+`<button class="new-card" onclick="newBook()"><div class="plus">${I('plus')}</div><h3>Une nouvelle histoire commence ici</h3><p>Importez votre PDF et<br>donnez vie à votre prochain livre.</p><span class="pill" style="margin-top:18px;background:transparent;color:#aea3b6">PDF · Jusqu’à 30 Mo</span></button>`}
async function ensureUser(){if(state.user)return true;state.user=await api('/auth/guest','POST',{});return true}
function authModal(mode='login'){modal(`<div class="brandmark">${I('book')}</div><h2>${mode==='login'?'Retrouvez votre atelier.':'Créez votre espace.'}</h2><p class="subtitle">Compte personnel sur cette installation. Vos projets sont séparés de ceux des autres utilisateurs.</p><form id="auth-form">${mode==='register'?'<label class="field">Votre nom<input name="name" required maxlength="60" autocomplete="name"></label>':''}<label class="field">Email<input name="email" type="email" required autocomplete="email"></label><label class="field">Mot de passe<input name="password" type="password" minlength="10" required autocomplete="${mode==='register'?'new-password':'current-password'}"><small>10 caractères minimum</small></label><button class="btn primary" style="width:100%" type="submit">${mode==='login'?'Se connecter':'Créer mon compte'}</button></form><div class="divider">ou</div><button class="btn" style="width:100%" onclick="authModal('${mode==='login'?'register':'login'}')">${mode==='login'?'Créer un compte':'J’ai déjà un compte'}</button>`);$('#auth-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));state.user=await api('/auth/'+mode,'POST',d);closeModal();await navigate('dashboard')}catch(e){toast(e.message)}}}
async function logout(){if(!confirm('Se déconnecter ? Une session découverte sans compte ne pourra pas être récupérée après déconnexion.'))return;await api('/logout','POST',{});state.user=null;state.projects=[];state.p=null;state.view='dashboard';renderDashboard()}
function newBook(){modal(`<span class="pill purple">VOTRE PROCHAIN CHAPITRE</span><h2>Tout commence par un PDF.</h2><p class="subtitle">Votre texte original est conservé. Nous créons une nouvelle mise en page, sans réécrire votre manuscrit.</p><div class="drop" id="drop-zone" role="button" tabindex="0" onclick="$('#pdf-input').click()" onkeydown="if(event.key==='Enter')$('#pdf-input').click()">${I('upload')}<strong>Glissez votre PDF ici</strong><small>ou cliquez pour choisir un fichier</small><small>PDF textuel · 30 Mo maximum · 250 pages</small></div><div class="notice info">Le PDF source reste téléchargeable à tout moment. Les documents scannés nécessitent un OCR préalable.</div><div class="divider">PAS DE MANUSCRIT SOUS LA MAIN ?</div><button class="btn" style="width:100%" onclick="createDemo()">${I('book')} Utiliser le PDF de démonstration ${I('arrow')}</button>${!state.user?`<p class="tiny muted" style="line-height:1.7;margin-top:17px">Un espace découverte privé sera créé. Pour retrouver vos livres avec un mot de passe, <button style="color:var(--purple);padding:0" onclick="authModal('register')">créez d’abord un compte</button>.</p>`:''}`);let drop=$('#drop-zone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('over')};drop.ondragleave=()=>drop.classList.remove('over');drop.ondrop=e=>{e.preventDefault();const f=e.dataTransfer.files[0];if(f)uploadPDF(f)}}
function demoModal(){modal(`<span class="pill green">UN VRAI PDF, UN VRAI PARCOURS</span><h2>Entreprendre autrement.</h2><p class="subtitle">Un guide fictif de 6 pages sur l’entrepreneuriat africain. Explorez le parcours avec un document créé spécialement pour le studio.</p><div class="notice info">Vous importerez un véritable PDF contenant du texte extractible. L’analyse locale, les prompts, la mise en page et les exports sont réels. Une illustration IA pré-générée avec Arena est fournie pour le chapitre 1. Elle n’est pas générée à chaque import. Les nouvelles générations nécessitent un modèle connecté.</div><button class="btn primary" style="width:100%;margin-top:24px" onclick="createDemo()">Créer mon livre de démonstration ${I('arrow')}</button>`)}
async function createDemo(){try{const b=$('.modal .btn.primary')||$('.modal .btn');if(b){b.disabled=true;b.innerHTML='<span class="spinner"></span> Création du PDF…'}await ensureUser();const p=await api('/projects/demo','POST',{});closeModal();state.projects=await api('/projects');await openProject(p.id);toast('PDF de démonstration créé. Lancez l’analyse pour composer votre livre.')}catch(e){toast(e.message);closeModal()}}
$('#pdf-input').onchange=e=>{const f=e.target.files[0];e.target.value='';if(f)uploadPDF(f)};
async function uploadPDF(file){try{if(file.size>30*1024*1024)throw Error('Le PDF dépasse la limite de 30 Mo.');await ensureUser();const data=new FormData();data.append('file',file);if($('#drop-zone'))$('#drop-zone').innerHTML='<span class="spinner"></span><strong style="margin-top:15px">Import du fichier…</strong>';const p=await api('/projects/upload','POST',data);closeModal();state.projects=await api('/projects');await openProject(p.id);toast('Votre PDF est importé et validé.')}catch(e){toast(e.message);newBook()}}
async function deleteProject(id){if(!confirm('Supprimer définitivement ce livre, son PDF source et tous ses exports ?'))return;try{await api('/projects/'+id,'DELETE');await navigate('dashboard');toast('Projet supprimé.')}catch(e){toast(e.message)}}
async function openProject(id,tab='structure'){try{if(dirty)await flush();clearTimeout(jobTimer);state.p=await api('/projects/'+id);state.view='editor';state.tab=tab;state.chapter=0;state.page=0;state.job=null;renderEditor();if(state.p.job){const j=await api('/jobs/'+state.p.job);if(['queued','running'].includes(j.status))watchJob(j)}}catch(e){toast(e.message)}}
function renderEditor(){const p=state.p;const content=`<div class="editor-head flex between"><div><button class="btn subtle small" style="padding:0;margin-bottom:12px" onclick="navigate('dashboard')">← Mes livres</button><h1>${E(p.title)}</h1><p class="subtitle">${E(p.source.filename)} · ${p.source.pages} pages source · ${(p.source.bytes/1024).toFixed(0)} Ko ${p.source.language?'· '+E(p.source.language):''}</p></div><div class="flex wrap gap">${p.book?`<span class="save-state" id="save-state">${I('cloud')} ${dirty||savePromise?'Enregistrement en attente…':'Enregistré'}</span><button class="iconbtn" title="Annuler" onclick="historyAction('undo')">${I('undo')}</button><button class="iconbtn" title="Rétablir" onclick="historyAction('redo')">${I('redo')}</button><button class="btn primary" onclick="openExport('${p.id}')">${I('download')} Exporter</button>`:`<a class="btn" href="${fileUrl(p,'original.pdf',true)}">${I('download')} PDF original</a>`}</div></div><div id="job-slot" style="margin-top:23px"></div>${p.book?`<nav class="tabs">${[['structure','file','Manuscrit'],['illustrations','image','Illustrations'],['layout','layout','Mise en page'],['cover','book','Couverture'],['quality','shield','Contrôle qualité'],['preview','eye','Aperçu']].map(([id,icon,label])=>`<button class="tab ${state.tab===id?'active':''}" onclick="switchTab('${id}')">${I(icon)}${label}</button>`).join('')}</nav><div id="editor-body">${tabContent()}</div>`:importPanel()}`;shell(content);renderJob();bindBookFields()}
function importPanel(){const p=state.p;return `<div class="panel" style="margin-top:25px"><div class="flex" style="align-items:flex-start;gap:20px"><div class="stat-icon">${I('file')}</div><div><h2>Votre manuscrit est arrivé.</h2><p style="margin-top:10px">Analysez son contenu pour créer une structure éditable et composer votre premier livre.</p></div></div><div class="file-summary"><div><small>FORMAT</small><b>PDF validé</b></div><div><small>PAGES SOURCE</small><b>${p.source.pages} pages</b></div><div><small>AUTEUR · MÉTADONNÉES</small><b>${E(p.source.author||'Non renseigné')}</b></div><div><small>TAILLE</small><b>${(p.source.bytes/1024).toFixed(0)} Ko</b></div></div><div class="notice info">Analyse gratuite sur le serveur : extraction du texte, détection des titres par typographie et suggestions d’illustrations à partir des passages. La langue et la structure sont des estimations à vérifier. Aucun modèle génératif n’est requis.</div><button class="btn primary" style="margin-top:24px" onclick="runJob('analyze')">${I('spark')} ANALYSER MON LIVRE</button></div>`}
async function switchTab(t){try{if(dirty)await flush();state.tab=t;renderEditor()}catch(e){toast(e.message)}}
function opt(list,current){return list.map(x=>`<option value="${E(x)}" ${x===current?'selected':''}>${E(x)}</option>`).join('')}
function input(label,path,value,type='text',attrs=''){return `<label class="field">${label}<input data-path="${path}" type="${type}" value="${E(value)}" ${attrs}></label>`}
function textarea(label,path,value,attrs=''){return `<label class="field">${label}<textarea data-path="${path}" ${attrs}>${E(value)}</textarea></label>`}
function select(label,path,values,current){return `<label class="field">${label}<select data-path="${path}">${opt(values,current)}</select></label>`}
function tabContent(){const p=state.p,b=p.book,s=b.settings;
if(state.tab==='structure'){const idx=Math.min(state.chapter,b.chapters.length-1);state.chapter=Math.max(0,idx);const ch=b.chapters[idx];return `<div class="notice info" style="margin-bottom:20px">${E(b.analysis_method)} ${p.source.tables?`${p.source.tables} tableau(x) détecté(s) : leur texte est extrait, mais leur structure visuelle n’est pas reconstruite.`:''}</div><div class="editor-grid"><div><div class="panel chapter-list">${b.chapters.map((c,i)=>`<div class="chapter-item ${i===idx?'active':''}"><span class="idx">${String(i+1).padStart(2,'0')}</span><button class="ctitle" style="text-align:left" onclick="selectChapter(${i})">${E(c.title)}</button><button title="Monter la section" onclick="moveChapter(${i},-1)">↑</button><button title="Descendre la section" onclick="moveChapter(${i},1)">↓</button></div>`).join('')}</div><button class="btn" style="width:100%" onclick="addChapter()">${I('plus')} Ajouter une section</button><div class="panel" style="margin-top:18px"><h3>À propos du manuscrit</h3><p class="tiny">${E(b.keywords.join(' · '))}</p><p style="margin-top:10px">Public : ${E(b.audience)}</p><button class="btn small" style="margin-top:14px" onclick="runJob('text-ai')">${I('spark')} Enrichir avec Text AI</button><p style="margin-top:10px;font-size:10px">Modèle local ou API à connecter. Le manuscrit ne sera pas réécrit.</p><a class="btn subtle small" href="${fileUrl(p,'original.pdf',true)}" style="padding:0;margin-top:16px">${I('download')} Télécharger le PDF source</a></div></div><div class="panel">${ch?`<div class="flex between" style="margin-bottom:18px"><h3 style="margin:0">${E(ch.title)}</h3><button class="iconbtn" title="Supprimer cette section" onclick="deleteChapter(${idx})">${I('trash')}</button></div><p class="tiny" style="margin-bottom:20px">Modifiez les blocs ci-dessous. Les sauts de page sont recalculés par le moteur ; les sections peuvent être réorganisées à gauche.</p>${ch.blocks.map((x,j)=>`<div class="block-editor"><div class="block-meta"><span>${x.kind==='heading'?'TITRE':x.kind==='title'?'TITRE DU LIVRE':x.kind==='quote'?'CITATION':'PARAGRAPHE'} · PAGE SOURCE ${x.page||'—'}</span><button title="Supprimer le bloc" class="iconbtn" onclick="deleteBlock(${idx},${j})">${I('trash')}</button></div><textarea class="${['title','heading'].includes(x.kind)?'heading':''}" aria-label="Texte du bloc ${j+1}" data-path="chapters.${idx}.blocks.${j}.text">${E(x.text)}</textarea></div>`).join('')}<button class="btn small" onclick="addBlock(${idx})">${I('plus')} Ajouter un paragraphe</button>`:'<p>Ajoutez une section pour commencer.</p>'}</div></div>`}
if(state.tab==='illustrations')return `<div class="panel"><div class="flex between wrap"><div><h3>Un univers visuel cohérent</h3><p>Des prompts construits à partir de vos passages, jamais des images sans rapport.</p></div><div class="flex gap"><select class="filter" data-path="settings.image_style">${opt(styles,s.image_style)}</select><button class="btn small" onclick="runJob('prompts')">Appliquer aux prompts</button></div></div><div class="notice info" style="margin-top:16px">Aucun modèle d’image n’est inclus. Importez vos images gratuitement ou connectez Stable Diffusion dans <button style="color:inherit;text-decoration:underline;padding:0" onclick="navigate('settings')">Paramètres → IA</button>. La cohérence des personnages n’est pas garantie par un simple prompt.</div></div>${b.suggestions.map((x,i)=>`<div class="panel illustration"><div><div class="image-slot">${x.asset?`<img src="${fileUrl(p,x.asset)}" alt="Illustration de ${E(x.section)}">`:`${I('image')}<small>Une idée attend de prendre forme.<br>Aucune image générée.</small>`}</div><div class="flex wrap gap" style="margin-top:10px"><button class="btn small" onclick="uploadImage(${i})">${I('upload')} ${x.asset?'Remplacer':'Importer'}</button>${x.asset?`<a class="iconbtn" title="Télécharger l’image" href="${fileUrl(p,x.asset,true)}">${I('download')}</a><button class="iconbtn" title="Retirer l’image" onclick="removeImage(${i})">${I('trash')}</button>`:''}</div></div><div><div class="flex between"><span class="pill purple">PAGE SOURCE ${x.page}</span><span class="tiny muted">${E(x.origin||'Suggestion locale')}</span></div><h3 style="margin:12px 0 0">${E(x.section)}</h3><div class="passage">« ${E(x.passage.slice(0,230))}${x.passage.length>230?'…':''} »</div><p style="font-size:11px;margin-bottom:12px">${E(x.idea)}</p>${textarea('Prompt de génération',`suggestions.${i}.prompt`,x.prompt)}<div class="formgrid">${select('Style',`suggestions.${i}.style`,styles,x.style)}${select('Placement dans le texte',`suggestions.${i}.position`,['before','after'],x.position)}</div>${x.asset?`<div class="formgrid">${input('Largeur (% de la zone)',`suggestions.${i}.width_pct`,x.width_pct,'number','min="20" max="100"')}${input('Légende',`suggestions.${i}.caption`,x.caption||'')}</div>`:''}<div class="flex between"><button class="btn primary small" onclick="generateImage(${i})">${I('spark')} ${x.asset?'Régénérer':'Générer l’illustration'}</button><button class="iconbtn" title="Supprimer la suggestion" onclick="deleteSuggestion(${i})">${I('trash')}</button></div></div></div>`).join('')}<button class="btn" onclick="addSuggestion()">${I('plus')} Ajouter une suggestion à la section sélectionnée</button>${p.source.source_images?.length?`<div class="panel" style="margin-top:20px"><h3>Images extraites du PDF source</h3><p>Sélectionnez une suggestion ci-dessus ou utilisez ces images comme couverture.</p><div class="flex wrap" style="margin-top:15px">${p.source.source_images.map(x=>`<div style="width:100px"><img src="${fileUrl(p,x.asset)}" style="width:100%;height:85px;object-fit:contain" alt="Image extraite de la page ${x.page}"><a class="btn small" href="${fileUrl(p,x.asset,true)}">Page ${x.page} ${I('download')}</a></div>`).join('')}</div></div>`:''}`;
if(state.tab==='layout')return `<div class="setting-grid"><div class="panel"><h3>La forme au service de votre texte</h3><div class="formgrid">${select('Format du livre','settings.format',['A4','A5','6 × 9','Personnalisé'],s.format)}${select('Composition','settings.layout',['Premium','Professionnel','Moderne','Minimaliste','Business','Éducatif','Magazine','Luxe'],s.layout)}${input('Largeur personnalisée (mm)','settings.width',s.width,'number','min="100" max="320"')}${input('Hauteur personnalisée (mm)','settings.height',s.height,'number','min="140" max="450"')}${input('Marges intérieures (mm)','settings.margin',s.margin,'number','min="10" max="35"')}${input('Corps du texte (pt)','settings.font_size',s.font_size,'number','min="8" max="16" step="0.5"')}<label class="field">Police<select data-path="settings.font"><option value="StudioSerif" ${s.font==='StudioSerif'?'selected':''}>DejaVu Serif — Littéraire</option><option value="StudioSans" ${s.font==='StudioSans'?'selected':''}>DejaVu Sans — Contemporaine</option></select></label>${input('Couleur d’accent','settings.accent',s.accent,'color')}</div><button class="btn primary" onclick="runJob('render')">${I('layout')} Recomposer le livre</button></div><div class="panel settings-aside"><h3>Une mise en page calculée</h3><p>Le moteur ajuste les sauts de page, conserve les proportions des images et évite les titres isolés lorsque c’est possible.</p><h4>Un aperçu fidèle</h4><p>L’aperçu est rendu directement depuis le PDF créé. Après une modification, utilisez « Recomposer » pour voir le nouveau résultat.</p><h4>Des compositions simples</h4><p>Premium, Professionnel, Moderne, Business, Éducatif et Luxe ouvrent les sections sur une nouvelle page. Minimaliste et Magazine privilégient un flux continu. Chaque composition possède ses tailles de titres, son interlignage, ses espacements et son alignement. La police, la couleur et les marges restent personnalisables.</p><div class="notice info">Pas de placement libre par glisser-déposer : les images s’ancrent avant ou après un bloc. Les pages sont calculées, pas éditées comme des diapositives.</div></div></div>`;
if(state.tab==='cover')return `<div class="setting-grid"><div class="panel"><h3>Première & quatrième de couverture</h3>${input('Titre','title',b.title,'text','maxlength="180"')}${input('Sous-titre','subtitle',b.subtitle,'text','maxlength="250"')}${input('Auteur','author',b.author,'text','maxlength="100"')}${textarea('Texte de quatrième de couverture','summary',b.summary,'maxlength="1300"')}<p class="tiny" style="margin:-6px 0 18px">${E(b.summary_method)}</p>${textarea('Présentation de l’auteur (facultative)','author_bio',b.author_bio,'maxlength="450"')}<div class="formgrid">${input('Épaisseur d’une feuille (mm)','settings.paper',s.paper,'number','min="0.05" max="0.3" step="0.01"')}${input('Fond perdu couverture (mm)','settings.bleed',s.bleed,'number','min="0" max="6" step="0.5"')}</div>${input('Couleur de couverture','settings.accent',s.accent,'color')}<div class="flex wrap"><button class="btn primary" onclick="runJob('render')">${I('book')} Créer la couverture</button><button class="btn" onclick="runJob('text-ai')">${I('spark')} Résumé avec Text AI</button></div></div><div><div class="panel"><h3>Illustration de couverture</h3><div class="image-slot">${b.cover_asset?`<img src="${fileUrl(p,b.cover_asset)}" alt="Image de couverture">`:`${I('book')}<small>Design typographique gratuit.<br>Aucune image IA simulée.</small>`}</div><div class="flex gap wrap" style="margin-top:13px"><button class="btn small" onclick="uploadImage('cover')">${I('upload')} Importer une image</button>${b.cover_asset?`<button class="btn small" onclick="removeImage('cover')">Retirer</button>`:''}</div>${b.suggestions.some(i=>i.asset)?`<label class="field" style="margin-top:18px">Réutiliser une illustration<select onchange="setCover(this.value)"><option value="">Choisir…</option>${b.suggestions.filter(i=>i.asset).map(i=>`<option value="${i.asset}">${E(i.section)}</option>`).join('')}</select></label>`:''}</div><div class="panel"><h3>Un dos à la bonne mesure</h3><p>Dos estimé = pages intérieures ÷ 2 × épaisseur d’une feuille. ${p.result?`Actuellement : <b>${p.result.spine_mm} mm</b>.`:''}</p><p style="margin-top:12px">Sous 5 mm, le texte du dos est omis. La couverture à plat comprend la quatrième, le dos et la première, avec le fond perdu renseigné.</p><div class="notice" style="margin-top:16px">Estimation à valider avec votre imprimeur. Le papier, la reliure et ses exigences déterminent la valeur finale.</div></div></div></div>`;
if(state.tab==='quality')return `<div class="panel"><div class="flex between wrap"><div><h3>Un dernier regard avant l’impression</h3><p>Contrôles effectués sur les fichiers réellement composés.</p></div><button class="btn" onclick="runJob('fix')">${I('spark')} Corriger automatiquement</button></div>${p.revision!==p.render_revision?'<div class="notice" style="margin-top:18px">Le livre a été modifié. Recomposez-le pour actualiser ce rapport.</div>':''}<div class="notice info" style="margin-top:18px">Correction automatique limitée : marges d’au moins 18 mm, fond perdu de 3 mm, réduction des images sous 300 ppp et recalcul de la pagination. Elle ne crée pas de pixels supplémentaires et ne certifie pas le PDF.</div>${(p.result?.quality||[]).map(q=>`<div class="quality-row ${q.status}">${I(q.status==='ok'?'check':q.status==='info'?'help':'warn')}<span>${E(q.text)}</span></div>`).join('')}<button class="btn primary" style="margin-top:20px" onclick="runJob('render')">${I('shield')} Recalculer et contrôler</button></div>`;
if(state.tab==='preview'){if(!p.result)return '<div class="empty">Recomposez le livre pour créer votre aperçu.</div>';return `${p.revision!==p.render_revision?'<div class="notice" style="margin-bottom:17px">Des modifications ne figurent pas encore dans ce PDF. <button style="text-decoration:underline" onclick="runJob(\'render\')">Recomposer maintenant</button></div>':''}<div class="reader" id="reader"><div class="preview-toolbar"><div class="flex gap"><button class="btn small" onclick="prevPage(-1)" aria-label="Page précédente">←</button><span id="page-label">${pageLabel()}</span><button class="btn small" onclick="prevPage(1)" aria-label="Page suivante">→</button></div><div class="flex gap"><button class="iconbtn" onclick="zoom(-10)" title="Dézoomer">−</button><span id="zoom-label">${state.zoom}%</span><button class="iconbtn" onclick="zoom(10)" title="Zoomer">+</button><button class="iconbtn" onclick="fullscreen()" title="Plein écran">${I('expand')}</button><a class="btn small" href="${fileUrl(p,'complete.pdf',true)}">${I('download')} PDF</a></div></div><div class="reader-body"><div class="thumbnails">${Array.from({length:p.result.preview_pages},(_,i)=>`<button class="thumb ${i===state.page?'active':''}" onclick="goPage(${i})" aria-label="Voir la page ${i+1}"><img loading="lazy" src="${fileUrl(p,'preview-'+i+'.png')}" alt="">${i===0?'Couverture':i===p.result.preview_pages-1?'Quatrième':i}</button>`).join('')}</div><div class="page-stage"><img id="preview-page" src="${fileUrl(p,'preview-'+state.page+'.png')}" alt="Page rendue du PDF exporté" style="width:${(innerWidth<600?260:430)*state.zoom/100}px"></div></div></div><p class="tiny muted" style="margin-top:16px">Cet aperçu est une image du PDF complet exporté, pas une approximation HTML. La couverture à plat avec le dos se télécharge séparément.</p>`}
return ''}
function bindBookFields(){$$('[data-path]').forEach(el=>el.oninput=()=>{let path=el.dataset.path.split('.'),obj=state.p.book;const key=path.pop();for(const k of path)obj=obj[k];obj[key]=el.type==='number'?Number(el.value):el.value;dirty=true;saveBadge('Modification en cours…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(e=>toast(e.message)),900)})}
function saveBadge(text){if($('#save-state'))$('#save-state').innerHTML=I('cloud')+' '+E(text)}
async function flush(){clearTimeout(saveTimer);if(savePromise){await savePromise;if(dirty)return flush();return}if(!dirty)return;const pid=state.p.id,revision=state.p.revision,book=JSON.parse(JSON.stringify(state.p.book));dirty=false;saveBadge('Enregistrement…');savePromise=(async()=>{try{const p=await api('/projects/'+pid,'PUT',{revision,book});if(state.p?.id===pid){state.p.revision=p.revision;state.p.updated=p.updated;state.p.title=p.title}saveBadge(dirty?'Modification en cours…':'Enregistré')}catch(e){dirty=true;saveBadge('Non enregistré');throw e}finally{savePromise=null}})();await savePromise}
function change(fn){fn();dirty=true;saveBadge('Modification en cours…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(e=>toast(e.message)),700);renderEditor()}
async function selectChapter(i){try{await flush();state.chapter=i;renderEditor()}catch(e){toast(e.message)}}
function moveChapter(i,d){const list=state.p.book.chapters;if(i+d<0||i+d>=list.length)return;change(()=>{[list[i],list[i+d]]=[list[i+d],list[i]];state.chapter=i+d})}
function addChapter(){const name=prompt('Titre de la nouvelle section','Nouvelle section');if(!name)return;change(()=>{state.p.book.chapters.push({id:crypto.randomUUID().replaceAll('-','').slice(0,12),title:name,blocks:[{id:crypto.randomUUID().replaceAll('-','').slice(0,12),kind:'heading',page:1,text:name},{id:crypto.randomUUID().replaceAll('-','').slice(0,12),kind:'paragraph',page:1,text:'Votre texte…'}]});state.chapter=state.p.book.chapters.length-1})}
function deleteChapter(i){if(!confirm('Supprimer cette section et ses suggestions ? Le PDF source sera conservé.'))return;change(()=>{const id=state.p.book.chapters[i].id;state.p.book.chapters.splice(i,1);state.p.book.suggestions=state.p.book.suggestions.filter(x=>x.chapter_id!==id);state.chapter=0})}
function addBlock(i){change(()=>state.p.book.chapters[i].blocks.push({id:crypto.randomUUID().replaceAll('-','').slice(0,12),text:'Votre texte…',kind:'paragraph',page:1}))}
function deleteBlock(i,j){if(!confirm('Supprimer ce bloc ?'))return;change(()=>{const [b]=state.p.book.chapters[i].blocks.splice(j,1);state.p.book.suggestions=state.p.book.suggestions.filter(x=>x.block_id!==b.id)})}
function removeImage(i){change(()=>{if(i==='cover')state.p.book.cover_asset=null;else state.p.book.suggestions[i].asset=null})}
function setCover(asset){if(asset)change(()=>state.p.book.cover_asset=asset)}
function deleteSuggestion(i){if(confirm('Supprimer cette suggestion et son illustration du livre ?'))change(()=>state.p.book.suggestions.splice(i,1))}
function uploadImage(i){assetCallback=i;$('#image-input').click()}
$('#image-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{await flush();const f=new FormData();f.append('file',file);const a=await api('/projects/'+state.p.id+'/assets','POST',f);change(()=>{if(assetCallback==='cover')state.p.book.cover_asset=a.asset;else{state.p.book.suggestions[assetCallback].asset=a.asset;state.p.book.suggestions[assetCallback].origin='Image importée'}});toast('Image importée. Recomposez le livre pour l’intégrer au PDF.')}catch(e){toast(e.message)}};
async function generateImage(i){try{const s=await api('/settings');if(!s.image_provider||s.image_provider==='none'){toast('Aucun modèle d’image connecté. Importez une image ou configurez Image AI dans les paramètres.');return}if(s.image_provider==='openai'&&!confirm('Le fournisseur externe peut facturer cette génération. Continuer ?'))return;const x=state.p.book.suggestions[i];if(!x.prompt.toLowerCase().includes(x.style.toLowerCase())){x.prompt=`Style: ${x.style}. `+x.prompt;dirty=true}await runJob('image',{suggestion:x.id})}catch(e){toast(e.message)}}
async function addSuggestion(){await sendCommand(`Ajoute une illustration au chapitre ${state.chapter+1}`)}
async function historyAction(d){try{await flush();state.p=await api('/projects/'+state.p.id+'/history/'+d,'POST',{});renderEditor();toast(d==='undo'?'Modification annulée.':'Modification rétablie.')}catch(e){toast(e.message)}}
async function runJob(action,payload={}){try{await flush();if(action==='text-ai'){const s=await api('/settings');if(s.text_provider==='openai'&&!confirm('Cette analyse enverra un extrait du livre au fournisseur externe et peut être facturée. Continuer ?'))return}const j=await api('/projects/'+state.p.id+'/run/'+action,'POST',payload);state.p.job=j.id;watchJob(j)}catch(e){toast(e.message)}}
function watchJob(j){state.job=j;renderJob();clearTimeout(jobTimer);if(j.status==='done'||j.status==='error')return;jobTimer=setTimeout(async()=>{try{const next=await api('/jobs/'+j.id);state.job=next;if(next.status==='done'){state.p=await api('/projects/'+j.project_id);dirty=false;state.projects=await api('/projects');renderEditor();toast('Traitement terminé. Les fichiers ont été créés.')}else if(next.status==='error'){renderJob();toast(next.error)}else watchJob(next)}catch(e){toast(e.message)}},1100)}
function renderJob(){const el=$('#job-slot');if(!el)return;const j=state.job;if(!j){el.innerHTML='';return}const pct=Math.round(j.completed/j.total*100);el.innerHTML=`<div class="job-box"><div class="flex between"><h3>${j.status==='error'?'Traitement interrompu':j.status==='done'?'Les fichiers sont prêts':`Traitement du livre · ${j.completed}/${j.total} étapes terminées`}</h3>${['queued','running'].includes(j.status)?'<span class="spinner"></span>':I(j.status==='done'?'check':'warn')}</div>${j.status==='error'?`<div class="notice">${E(j.error)}</div>`:`<div class="job-track"><span style="width:${pct}%"></span></div><div class="job-steps">${j.steps.map((s,i)=>`<span class="${i<j.completed?'done':i===j.completed?'current':''}">${i<j.completed?'✓':i===j.completed&&j.status!=='done'?'◌':'○'} ${E(s)}</span>`).join('')}</div>`}</div>`;const running=['queued','running'].includes(j.status);$$('#editor-body input,#editor-body select,#editor-body textarea,#editor-body button,.editor-head button,#editor-body a.btn').forEach(el=>{if(el.tagName!=='A')el.disabled=running})}
function pageLabel(){return state.page===0?'Première de couverture':state.page===state.p.result.preview_pages-1?'Quatrième de couverture':`Page ${state.page} / ${state.p.result.pages}`}
function goPage(i){state.page=i;$('#preview-page').src=fileUrl(state.p,'preview-'+i+'.png');$('#page-label').textContent=pageLabel();$$('.thumb').forEach((el,n)=>el.classList.toggle('active',n===i))}
function prevPage(d){goPage(Math.max(0,Math.min(state.p.result.preview_pages-1,state.page+d)))}
function zoom(d){state.zoom=Math.max(40,Math.min(220,state.zoom+d));$('#zoom-label').textContent=state.zoom+'%';$('#preview-page').style.width=(innerWidth<600?260:430)*state.zoom/100+'px'}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#reader').requestFullscreen()}catch(e){toast('Le plein écran n’est pas autorisé dans ce navigateur.')}}
async function openExport(id){try{if(dirty)await flush();const p=await api('/projects/'+id);if(!p.result){toast('Analysez et composez le livre pour créer ses fichiers.');return}modal(`<span class="pill green">FICHIERS CRÉÉS SUR LE SERVEUR</span><h2>Votre livre, prêt à partir.</h2><p class="subtitle">${E(p.title)} · ${p.result.pages} pages intérieures${p.revision!==p.render_revision?' · Une version antérieure est disponible.':''}</p>${p.revision!==p.render_revision?`<div class="notice" style="margin-bottom:18px">Des modifications ne figurent pas dans ces fichiers. <button style="text-decoration:underline" onclick="closeModal();openProject('${id}').then(()=>runJob('render'))">Recomposer avant de télécharger</button></div>`:''}${[['complete.pdf','PDF complet','Lecture : première, intérieur et quatrième'],['interior.pdf','PDF intérieur','Pages seules, format choisi, polices incorporées'],['cover.pdf','PDF couverture à plat','Quatrième + dos + première, avec fond perdu'],['book.epub','EPUB texte','Édition numérique refluable, sans illustrations']].map(([file,label,desc])=>`<a href="${fileUrl(p,file,true)}" class="flex between" style="padding:17px 0;border-bottom:1px solid var(--line)"><div class="flex">${I(file.endsWith('epub')?'book':'file')}<div><h3 style="font-size:12px">${label}</h3><p class="muted" style="font-size:10px;margin-top:5px">${desc}</p></div></div>${I('download')}</a>`).join('')}<div class="notice" style="margin-top:20px">PDF non certifié PDF/X. Consultez le contrôle qualité et faites valider le profil couleur, le papier et le dos par votre imprimeur.</div>`)}catch(e){toast(e.message)}}
function assistantWidget(){const old=$('.assistant');if(old)old.remove();const el=document.createElement('div');el.className='assistant';el.innerHTML=`${state.assistant?`<div class="assistant-box"><div class="flex between"><h3 class="flex gap">${I('spark')} Assistant du studio</h3><button class="iconbtn" title="Fermer l’assistant" onclick="state.assistant=false;assistantWidget()">${I('close')}</button></div><p>Mode local à règles, sans LLM. Commandes limitées et réelles. Les numéros de page désignent le PDF source.</p><div class="assistant-answer" id="assistant-answer">Essayez « Corrige les problèmes de mise en page », « Ajoute une illustration au chapitre 2 » ou « Mets les illustrations en style 3D ».</div><textarea id="assistant-command" placeholder="Que souhaitez-vous modifier ?" aria-label="Commande de l’assistant"></textarea><button class="btn primary small" style="width:100%" onclick="sendCommand($('#assistant-command').value)">Appliquer la commande ${I('arrow')}</button></div>`:''}<button class="assistant-launch" title="Ouvrir l’assistant" onclick="state.assistant=!state.assistant;assistantWidget()">${I('spark')}</button>`;document.body.appendChild(el)}
async function sendCommand(command){if(!command.trim())return;try{await flush();if(/change.*image|génère|regen/i.test(command)){const s=await api('/settings');if(s.image_provider==='openai'&&!confirm('Génération externe potentiellement payante. Continuer ?'))return}const r=await api('/projects/'+state.p.id+'/assistant','POST',{command});if(r.job)watchJob(r.job);else{state.p=await api('/projects/'+state.p.id);renderEditor()}if($('#assistant-answer'))$('#assistant-answer').textContent=r.message;else toast(r.message)}catch(e){if($('#assistant-answer'))$('#assistant-answer').textContent=e.message;else toast(e.message)}}
async function renderSettings(){const s=await api('/settings');shell(`<div class="welcome"><div class="eyebrow" style="margin-bottom:12px">LES OUTILS DE VOTRE ATELIER</div><h1>Une IA, à votre mesure.</h1><p>Commencez gratuitement. Connectez vos modèles quand vous en avez besoin.</p></div><div class="setting-grid" style="margin-top:28px"><form id="settings-form"><div class="panel"><h3 class="flex">${I('file')} Text AI</h3><label class="field">Fournisseur<select name="text_provider">${[['none','Analyse locale uniquement — gratuite'],['ollama','Ollama — modèle open source local'],['openai','OpenAI — API externe, potentiellement payante']].map(([v,l])=>`<option value="${v}" ${s.text_provider===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Modèle<input name="text_model" value="${E(s.text_model||'')}" placeholder="qwen2.5:3b (Ollama) ou gpt-4o-mini"><small>Ollama : modèle à télécharger sur le serveur, port 11434.</small></label><label class="field">Clé API Text AI<input name="text_key" type="password" autocomplete="new-password" placeholder="${s.text_key_set?'Clé enregistrée — laissez vide pour conserver':'Optionnelle, jamais renvoyée au navigateur'}"></label></div><div class="panel"><h3 class="flex">${I('image')} Image AI</h3><label class="field">Fournisseur<select name="image_provider">${[['none','Import d’images uniquement — gratuit'],['a1111','Stable Diffusion — AUTOMATIC1111 local'],['openai','OpenAI Images — API externe payante']].map(([v,l])=>`<option value="${v}" ${s.image_provider===v?'selected':''}>${l}</option>`).join('')}</select></label><p style="margin-bottom:16px">Stable Diffusion doit être installé séparément sur le serveur et lancé avec <code>--api</code> sur le port 7860. Un GPU adapté est recommandé. Aucun modèle n’est préinstallé.</p><label class="field">Clé API Image AI<input name="image_key" type="password" autocomplete="new-password" placeholder="${s.image_key_set?'Clé enregistrée — laissez vide pour conserver':'Nécessaire uniquement pour OpenAI'}"></label></div><div class="panel"><h3 class="flex">${I('eye')} Vision AI <span class="pill">Extension prévue</span></h3><p style="margin-bottom:15px">L’analyse visuelle et l’OCR ne sont pas intégrés dans cette version. La clé peut être conservée pour une intégration future, mais aucun appel Vision n’est effectué.</p><label class="field">Clé API Vision AI<input name="vision_key" type="password" autocomplete="new-password" placeholder="${s.vision_key_set?'Clé enregistrée':'Facultative — connecteur non implémenté'}"></label></div><div class="flex wrap"><button class="btn primary" type="submit">${I('check')} Enregistrer les paramètres</button><button class="btn danger" type="button" onclick="clearKeys()">Supprimer les clés</button></div></form><div class="panel settings-aside"><span class="pill green">0 € POUR COMMENCER</span><h3 style="margin-top:20px">Pas de frais cachés.</h3><p>L’extraction PDF, la structure heuristique, les prompts, la composition, la couverture typographique et les exports fonctionnent sans clé API.</p><h4>Votre serveur, vos modèles</h4><p>Ollama et Stable Diffusion sont des logiciels gratuits. Leur installation et leurs besoins matériels restent à votre charge. Aucun free tier distant instable n’est activé par défaut.</p><h4>Clés côté serveur</h4><p>Les clés sont enregistrées dans la base privée, jamais incluses dans les réponses API. Elles ne sont utilisées que lors d’une demande explicite.</p><div class="notice">Installation de développement : chiffrez le disque et ajoutez HTTPS, des sauvegardes et une gestion de secrets avant toute exploitation publique. Pas de chiffrement applicatif des clés dans cette version.</div>${state.user&&!state.user.email?`<div class="notice info" style="margin-top:15px">Vous utilisez une session découverte. Elle est liée à ce navigateur pendant 7 jours et ne possède pas de mécanisme de récupération.</div>`:''}</div></div>`);$('#settings-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));for(const k of ['text_key','image_key','vision_key'])if(!d[k])delete d[k];await api('/settings','PUT',d);toast('Paramètres enregistrés côté serveur.');await renderSettings()}catch(e){toast(e.message)}}}
async function clearKeys(){if(!confirm('Supprimer toutes les clés API de cet espace ?'))return;await api('/settings','PUT',{text_key:'',image_key:'',vision_key:''});await renderSettings();toast('Clés supprimées.')}
function renderHelp(){shell(`<div class="welcome"><div class="eyebrow" style="margin-bottom:12px">UN STUDIO TRANSPARENT</div><h1>Du premier PDF au dernier détail.</h1><p>Ce qui fonctionne aujourd’hui, et ce qui nécessite un outil supplémentaire.</p></div><div class="help-grid" style="margin-top:28px"><div class="panel"><h3>01. Importez votre manuscrit</h3><p>Choisissez un PDF textuel de moins de 30 Mo et 250 pages. Le PDF original n’est jamais modifié. Les PDF scannés ou chiffrés sont refusés avec une explication.</p></div><div class="panel"><h3>02. Analysez et vérifiez la structure</h3><p>L’analyse locale s’appuie sur la taille des caractères et la typographie. Elle n’est pas une compréhension sémantique par LLM. Vous pouvez ensuite enrichir le public et le résumé avec un modèle Text AI connecté.</p></div><div class="panel"><h3>03. Donnez une place aux images</h3><p>Les prompts utilisent des extraits réels du manuscrit. Importez une illustration ou utilisez un fournisseur configuré. L’IA distante peut être payante ; le modèle local nécessite une installation séparée.</p></div><div class="panel"><h3>04. Composez et exportez</h3><p>Modifiez la police, le format, les marges et la couverture, puis recomposez. L’aperçu montre le PDF réel. Les fichiers intérieur et couverture à plat sont séparés pour faciliter le travail de l’imprimeur.</p></div></div><div class="panel"><h3>Les limites de cette version</h3><p>Pas d’OCR ni de Vision AI. Pas d’éditeur de pages en glisser-déposer. L’ordre et l’ajout/suppression s’appliquent aux sections ; la pagination est calculée. Les tableaux complexes ne sont pas reconstruits. Les compositions sont simples et non des templates éditoriaux avancés. L’EPUB contient le texte, sans images. Le contrôle automatique ne remplace pas une vérification visuelle et le PDF n’est pas certifié PDF/X. Le résumé gratuit est un extrait, pas un résumé généré. L’assistant gratuit applique un ensemble limité de commandes à règles.</p></div><div class="panel"><h3>Un espace privé, pas encore une infrastructure de production</h3><p>Authentification par mot de passe haché, cookies de session HTTP-only, contrôles d’accès aux projets, validations et limites de fichiers. Les traitements utilisent une file locale ; ils ne sont pas repris automatiquement après un redémarrage. Avant une ouverture publique : chiffrement du disque, HTTPS, sauvegardes, isolation des parseurs PDF, quotas globaux, antivirus, réinitialisation des mots de passe et vérification des emails restent à ajouter.</p></div><button class="btn primary" onclick="demoModal()">${I('book')} Tester avec le livre de démonstration</button>`)}
window.addEventListener('beforeunload',e=>{if(dirty||savePromise){e.preventDefault();e.returnValue=''}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(state.view==='editor'&&state.tab==='preview'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){if(e.key==='ArrowRight')prevPage(1);if(e.key==='ArrowLeft')prevPage(-1)}});
// Clear detached assistant when leaving the editor.
const shellBase=shell;shell=function(content){$('.assistant')?.remove();shellBase(content)};
(async()=>{try{state.user=await api('/me');state.projects=await api('/projects')}catch{}renderDashboard()})();
